func truncationEscalationCeiling(aiServiceConfig map[string]interface{}) (int, bool) {
	if aiServiceConfig == nil {
		return 0, false
	}
	switch v := aiServiceConfig["max_tokens_ceiling"].(type) {
	case int:
		if v > 0 { return v, true }
	case int64:
		if v > 0 { return int(v), true }
	case float64:
		if v > 0 { return int(v), true }
	case json.Number:
		if n, err := v.Int64(); err == nil && n > 0 { return int(n), true }
	}
	return 0, false
}

func truncationEscalationApplies(err error, aiServiceConfig map[string]interface{}, sentMaxTokens int) (int, bool) {
	if _, isTrunc := aiservice.IsTruncated(err); !isTrunc {
		return 0, false
	}
	ceiling, ok := truncationEscalationCeiling(aiServiceConfig)
	if !ok || ceiling <= sentMaxTokens {
		return 0, false
	}
	return ceiling, true
}

cases := []struct{ name string; err error; cfg map[string]interface{}; sent, wantCeiling int; wantOK bool }{
	{"truncated with taller ceiling escalates", truncated(16000), cfgWith(float64(32000)), 16000, 32000, true},
	{"truncated with no ceiling stays off", truncated(16000), map[string]interface{}{"max_tokens": float64(16000)}, 16000, 0, false},
	{"ceiling equal to sent cap refuses", truncated(16000), cfgWith(float64(16000)), 16000, 0, false},
	{"non-truncation error never escalates", errors.New("529 overloaded"), cfgWith(float64(32000)), 16000, 0, false},
	{"wrapped truncation escalates", fmt.Errorf("AI call failed: %w", truncated(16000)), cfgWith(float64(32000)), 16000, 32000, true},
	{"escalates over the provider fallback", truncated(2048), cfgWith(float64(32000)), 2048, 32000, true},
}
for _, tc := range cases {
	ceiling, ok := truncationEscalationApplies(tc.err, tc.cfg, tc.sent)
	if ok != tc.wantOK || ceiling != tc.wantCeiling { t.Fatalf(...) }
}

